SELECT p.Id FROM profiles.Profiles p WHERE p.TenantId = @tenant AND p.MergedIntoId IS NULL AND ((JSON_VALUE(p.Attributes, '$.k01') IS NOT NULL AND JSON_VALUE(p.Attributes, '$.k02') IS NOT NULL AND JSON_VALUE(p.Attributes, '$.k03') IS NOT NULL AND JSON_VALUE(p.Attributes, '$.k04') IS NOT NULL AND JSON_VALUE(p.Attributes, '$.k05') IS NOT NULL AND JSON_VALUE(p.Attributes, '$.k06') IS NOT NULL AND JSON_VALUE(p.Attributes, '$.k07') IS NOT NULL AND JSON_VALUE(p.Attributes, '$.k08') IS NOT NULL AND JSON_VALUE(p.Attributes, '$.k09') IS NOT NULL AND JSON_VALUE(p.Attributes, '$.k10') IS NOT NULL AND JSON_VALUE(p.Attributes, '$.k11') IS NOT NULL AND JSON_VALUE(p.Attributes, '$.k12') IS NOT NULL AND JSON_VALUE(p.Attributes, '$.k13') IS NOT NULL AND JSON_VALUE(p.Attributes, '$.k14') IS NOT NULL AND JSON_VALUE(p.Attributes, '$.k15') IS NOT NULL AND JSON_VALUE(p.Attributes, '$.k16') IS NOT NULL AND JSON_VALUE(p.Attributes, '$.k17') IS NOT NULL AND JSON_VALUE(p.Attributes, '$.k18') IS NOT NULL AND JSON_VALUE(p.Attributes, '$.k19') IS NOT NULL AND JSON_VALUE(p.Attributes, '$.k20') IS NOT NULL))

@tenant = 00000000-0000-0000-0000-000000000001
